from fastapi import FastAPI
from fastapi.testclient import TestClient
from pydantic import BaseModel


class Item(BaseModel):
    name: str
    description: str | None = None
    price: float | None = None


def _make_payload() -> Item:
    return Item(name="widget", description=None, price=None)


def test_app_default_true_excludes_none_fields_from_route_response():
    """When `default_response_model_exclude_none=True`, routes that do not
    explicitly set `response_model_exclude_none` should drop fields whose
    value is `None` from the JSON response.
    """
    app = FastAPI(default_response_model_exclude_none=True)

    @app.get("/item", response_model=Item)
    def get_item() -> Item:
        return _make_payload()

    client = TestClient(app)
    response = client.get("/item")

    assert response.status_code == 200, response.text
    assert response.json() == {"name": "widget"}


def test_app_default_false_keeps_none_fields_in_route_response():
    """When `default_response_model_exclude_none=False` (the default), routes
    that do not explicitly set `response_model_exclude_none` should keep
    fields whose value is `None` in the JSON response.
    """
    app = FastAPI()

    @app.get("/item", response_model=Item)
    def get_item() -> Item:
        return _make_payload()

    client = TestClient(app)
    response = client.get("/item")

    assert response.status_code == 200, response.text
    assert response.json() == {
        "name": "widget",
        "description": None,
        "price": None,
    }


def test_per_route_explicit_false_overrides_app_default_true():
    """A route that explicitly sets `response_model_exclude_none=False` must
    override the app-level default of `True`, keeping `None` fields in its
    response, while sibling routes that don't override still drop them.
    """
    app = FastAPI(default_response_model_exclude_none=True)

    @app.get("/inherits", response_model=Item)
    def get_inherits() -> Item:
        return _make_payload()

    @app.get(
        "/overridden",
        response_model=Item,
        response_model_exclude_none=False,
    )
    def get_overridden() -> Item:
        return _make_payload()

    client = TestClient(app)

    # Inherits the app-level default: None fields are dropped.
    inherits = client.get("/inherits")
    assert inherits.status_code == 200, inherits.text
    assert inherits.json() == {"name": "widget"}

    # Explicit per-route override: None fields are kept.
    overridden = client.get("/overridden")
    assert overridden.status_code == 200, overridden.text
    assert overridden.json() == {
        "name": "widget",
        "description": None,
        "price": None,
    }

